window.products.push({"id":480570,"name":"Bodum Kenya 4-Cup Tea Press, Black","category":"homeandappliances","retail price":0.0,"sale price":null,"image":"https://m.media-amazon.com/images/I/417NM19NWKL._AC_.jpg","description":"Make brewing loose leaf tea a snap with the Kenya 4 Cup Tea Press. Just put the loose leaf tea into the infuser, add hot water, steep to your liking and then press to stop the brewing process. Now you can serve and enjoy your tea knowing that brewing has stopped and your tea will not become \"stewed\" or bitter. The Kenya 4 Cup Tea Press is 32 oz and yields 4 - 8 ounce cups of tea.","images":["https://m.media-amazon.com/images/I/417NM19NWKL._AC_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"Bodum","source_asin":"B0000U6PW2","category_path":"Home & Kitchen"},"sku":"BM-480570","productType":"Home & Appliances","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B0000U6PW2","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"meta_Home_and_Kitchen_2023.jsonl","source_asin":"B0000U6PW2","price_pending":true,"merchant_ready":false});
